using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying)
                throw new Exception("Play");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/ui-profile");
            s.data.mapping.Clear();
            s.data.evidence.RemoveAll(e => e.id == "decoded");
            s.OpenPage("cipher");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            Action<float, float> click = (x, y) =>
            {
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = new Vector2(x / 1.25f, (y + 55) / 1.25f)});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = new Vector2(x / 1.25f, (y + 55) / 1.25f)});
            };
            Action<char, KeyCode> key = (c, k) =>
            {
                w.SendEvent(new Event{type = EventType.KeyDown, character = c, keyCode = k});
                w.SendEvent(new Event{type = EventType.KeyUp, character = c, keyCode = k});
            };
            var log = new StringBuilder("GameView.SendEvent synthetic mouse/text, API prepares private test state only.\n");
            int step = 0;
            double next = EditorApplication.timeSinceStartup + .7;
            EditorApplication.CallbackFunction tick = null;
            tick = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .7;
                try
                {
                    switch (step++)
                    {
                        case 0:
                            click(455, 565);
                            key('Z', KeyCode.Z);
                            break;
                        case 1:
                            log.AppendLine("field wrong Z=" + (s.data.mapping.FirstOrDefault(m => m.pose == "A")?.letter == "Z"));
                            click(455, 565);
                            key('\0', KeyCode.Backspace);
                            break;
                        case 2:
                            log.AppendLine("mapping=" + string.Join(",", s.data.mapping.Select(m => m.pose + "=" + m.letter)));
                            log.AppendLine("clear=" + string.IsNullOrEmpty(s.data.mapping.FirstOrDefault(m => m.pose == "A")?.letter));
                            click(455, 565);
                            key('A', KeyCode.A);
                            break;
                        case 3:
                            log.AppendLine("mapping=" + string.Join(",", s.data.mapping.Select(m => m.pose + "=" + m.letter)));
                            log.AppendLine("assign A=" + (s.data.mapping.FirstOrDefault(m => m.pose == "A")?.letter == "A"));
                            click(800, 783);
                            break;
                        case 4:
                            log.AppendLine("hint user-open=" + "inspect screenshot for visible hint");
                            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/cipher-ui-typed.png");
                            click(160, 264);
                            break;
                        case 5:
                            log.AppendLine("compare button page=" + s.Page);
                            click(700, 409);
                            click(1450, 648);
                            break;
                        case 6:
                            log.AppendLine("Compare selections checked visually; no reflection");
                            w.SendEvent(new Event{type = EventType.ScrollWheel, mousePosition = new Vector2(1100, 700), delta = new Vector2(0, 110)});
                            break;
                        case 7:
                            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/compare-ui-selected.png");
                            File.WriteAllText("Test/KetQua/investigation_r102/ui-input-check.txt", log.ToString());
                            EditorApplication.update -= tick;
                            break;
                    }
                }
                catch (Exception e)
                {
                    log.AppendLine(e.ToString());
                    File.WriteAllText("Test/KetQua/investigation_r102/ui-input-check.txt", log.ToString());
                    EditorApplication.update -= tick;
                }
            };
            EditorApplication.update += tick;
            r.Log("Started real UI mouse/text/scroll checks, final log in6s");
        }
    }
}

